class Solution {
    public int canCompleteCircuit(int[] gas, int[] cost) {
        int total = 0;
        int tank = 0;
        int start = 0;
        for (int station = 0; station < gas.length; station++) {
            int net = gas[station] - cost[station];
            total += net;
            tank += net;
            if (tank < 0) {
                start = station + 1;
                tank = 0;
            }
        }
        return total >= 0 ? start : -1;
    }
}
